package com.novara.banking.card;
import com.novara.banking.audit.AuditService; import com.novara.banking.identity.CurrentIdentity.FederatedIdentity; import com.novara.banking.shared.DomainException;
import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.sql.*; import java.util.*;
@Service public class CardService {
 private final JdbcClient jdbc; private final CardProcessor processor; private final AuditService audit;
 public CardService(JdbcClient jdbc,CardProcessor processor,AuditService audit){this.jdbc=jdbc;this.processor=processor;this.audit=audit;}
 public List<CardView> list(FederatedIdentity i){long c=customer(i);return jdbc.sql(VIEW+" WHERE x.customer_id=:c ORDER BY x.created_at").param("c",c).query(this::map).list();}
 public CardView owned(FederatedIdentity i,UUID id){return jdbc.sql(VIEW+" WHERE x.customer_id=:c AND x.public_id=:id").param("c",customer(i)).param("id",id).query(this::map).optional().orElseThrow(this::notFound);}
 @Transactional public CardView status(FederatedIdentity i,UUID id,String target,String key,String correlation){
  validateKey(key); long customer=customer(i); CardRow row=lock(customer,id); String hash=sha(id+"|"+target); var prior=prior(customer,"CARD_STATUS",key,hash); if(prior!=null)return owned(i,id);
  String expected=target.equals("FROZEN")?"ACTIVE":"FROZEN";
  if(!Set.of("FROZEN","ACTIVE").contains(target)||!row.status.equals(expected))throw conflict("INVALID_CARD_TRANSITION","This card cannot move from "+row.status+" to "+target+".");
  var result=processor.changeStatus(row.processor,target); recordRequest(customer,row.id,"CARD_STATUS",key,hash,result);
  if(!result.acknowledged())throw conflict("PROCESSOR_NOT_ACKNOWLEDGED","The sandbox processor did not confirm the card status change.");
  jdbc.sql("UPDATE cards SET status=:s,version=version+1,updated_at=now() WHERE id=:id").param("s",target).param("id",row.id).update();
  jdbc.sql("INSERT INTO card_status_events(card_id,previous_status,new_status,processor_acknowledged) VALUES(:id,:old,:new,true)").param("id",row.id).param("old",row.status).param("new",target).update();
  audit.record(i.subject(),"CARD_"+target,"CARD",id,"SUCCESS",correlation,"{\"sandboxProcessorAcknowledged\":true}"); return owned(i,id);
 }
 @Transactional public CardView controls(FederatedIdentity i,UUID id,CardCommands.Controls c,String key,String correlation){
  validateKey(key); if(c.dailyLimitMinor()<Math.max(Math.max(c.atmLimitMinor(),c.onlineLimitMinor()),Math.max(c.posLimitMinor(),c.contactlessLimitMinor())))throw invalid("INVALID_CARD_LIMIT","Daily limit must cover every channel limit.");
  long customer=customer(i);CardRow row=lock(customer,id);if(!Set.of("ACTIVE","FROZEN").contains(row.status))throw conflict("CARD_CONTROLS_UNAVAILABLE","Controls are unavailable for this card status.");
  if(c.version()!=row.controlVersion)throw conflict("CARD_VERSION_CONFLICT","Card controls changed in another session. Refresh before trying again.");
  String hash=sha(id+"|"+c);var prior=prior(customer,"CARD_CONTROLS",key,hash);if(prior!=null)return owned(i,id);var result=processor.updateControls(row.processor,c);recordRequest(customer,row.id,"CARD_CONTROLS",key,hash,result);
  if(!result.acknowledged())throw conflict("PROCESSOR_NOT_ACKNOWLEDGED","The sandbox processor did not confirm the control change.");
  int changed=jdbc.sql("UPDATE card_controls SET atm_enabled=:atm,online_enabled=:online,pos_enabled=:pos,contactless_enabled=:tap,international_enabled=:intl,atm_limit_minor=:al,online_limit_minor=:ol,pos_limit_minor=:pl,contactless_limit_minor=:cl,daily_limit_minor=:dl,version=version+1,updated_at=now() WHERE card_id=:id AND version=:version")
   .param("atm",c.atmEnabled()).param("online",c.onlineEnabled()).param("pos",c.posEnabled()).param("tap",c.contactlessEnabled()).param("intl",c.internationalEnabled()).param("al",c.atmLimitMinor()).param("ol",c.onlineLimitMinor()).param("pl",c.posLimitMinor()).param("cl",c.contactlessLimitMinor()).param("dl",c.dailyLimitMinor()).param("id",row.id).param("version",c.version()).update();
  if(changed!=1)throw conflict("CARD_VERSION_CONFLICT","Card controls changed in another session. Refresh before trying again.");
  audit.record(i.subject(),"CARD_CONTROLS_UPDATED","CARD",id,"SUCCESS",correlation,"{\"sandboxProcessorAcknowledged\":true,\"stepUpVerified\":true}");return owned(i,id);
 }
 @Transactional public CardView.Service request(FederatedIdentity i,UUID id,CardCommands.ServiceRequest r,String correlation){long c=customer(i);CardRow row=lock(c,id);UUID publicId=UUID.randomUUID();jdbc.sql("INSERT INTO card_service_requests(public_id,card_id,customer_id,request_type,notes) VALUES(:p,:card,:c,:type,:notes)").param("p",publicId).param("card",row.id).param("c",c).param("type",r.requestType()).param("notes",r.notes()).update();audit.record(i.subject(),"CARD_SERVICE_REQUESTED","CARD",id,"SUCCESS",correlation,"{\"issuerFulfilmentPending\":true}");return new CardView.Service(publicId,r.requestType(),"SUBMITTED",r.notes(),java.time.Instant.now());}
 public CardView.ActivityPage activity(FederatedIdentity i,UUID id,int page,int size,String search,String status,java.time.LocalDate from,java.time.LocalDate to,String direction){long c=customer(i);owned(i,id);if(status!=null&&!Set.of("PENDING","COMPLETED","REVERSED","DECLINED").contains(status))throw invalid("INVALID_CARD_TRANSACTION_STATUS","The transaction status filter is invalid.");String order="asc".equalsIgnoreCase(direction)?"ASC":"DESC";String filters=" AND (:search='' OR t.merchant_description ILIKE '%'||:search||'%') AND (:status IS NULL OR t.status=:status) AND (:from IS NULL OR t.occurred_at>=:from) AND (:to IS NULL OR t.occurred_at<:to+interval '1 day')";long total=jdbc.sql("SELECT count(*) FROM card_transactions t JOIN cards x ON x.id=t.card_id WHERE t.customer_id=:c AND x.public_id=:id"+filters).param("c",c).param("id",id).param("search",search).param("status",status,Types.VARCHAR).param("from",from,Types.DATE).param("to",to,Types.DATE).query(Long.class).single();var content=jdbc.sql("SELECT t.public_id,t.merchant_description,t.amount_minor,t.currency,t.status,t.transaction_type,x.masked_reference,t.occurred_at FROM card_transactions t JOIN cards x ON x.id=t.card_id WHERE t.customer_id=:c AND x.public_id=:id"+filters+" ORDER BY t.occurred_at "+order+",t.id "+order+" LIMIT :size OFFSET :offset").param("c",c).param("id",id).param("search",search).param("status",status,Types.VARCHAR).param("from",from,Types.DATE).param("to",to,Types.DATE).param("size",size).param("offset",Math.multiplyExact(page,size)).query((r,n)->new CardView.Activity(r.getObject(1,UUID.class),r.getString(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getTimestamp(8).toInstant())).list();return new CardView.ActivityPage(content,page,size,total,(int)((total+size-1)/size));}
 private long customer(FederatedIdentity i){return jdbc.sql("SELECT id FROM customers WHERE identity_issuer=:issuer AND identity_subject=:subject AND status='ACTIVE'").param("issuer",i.issuer()).param("subject",i.subject()).query(Long.class).optional().orElseThrow(this::notFound);}
 private CardRow lock(long c,UUID id){return jdbc.sql("SELECT x.id,x.status,x.processor_reference,cc.version FROM cards x JOIN card_controls cc ON cc.card_id=x.id WHERE x.customer_id=:c AND x.public_id=:id FOR UPDATE OF x,cc").param("c",c).param("id",id).query((r,n)->new CardRow(r.getLong(1),r.getString(2),r.getString(3),r.getLong(4))).optional().orElseThrow(this::notFound);}
 private String prior(long c,String type,String key,String hash){return jdbc.sql("SELECT request_hash FROM card_control_requests WHERE customer_id=:c AND request_type=:t AND idempotency_key=:k").param("c",c).param("t",type).param("k",key).query(String.class).optional().map(v->{if(!v.equals(hash))throw conflict("IDEMPOTENCY_KEY_REUSED","The key was used for a different card command.");return v;}).orElse(null);}
 private void recordRequest(long c,long card,String type,String key,String hash,CardProcessor.Result r){jdbc.sql("INSERT INTO card_control_requests(card_id,customer_id,request_type,idempotency_key,request_hash,status,processor_reference,failure_code,completed_at) VALUES(:card,:c,:type,:key,:hash,:status,:ref,:failure,now())").param("card",card).param("c",c).param("type",type).param("key",key).param("hash",hash).param("status",r.acknowledged()?"CONFIRMED":"FAILED").param("ref",r.reference()).param("failure",r.failureCode(),Types.VARCHAR).update();}
 private CardView map(ResultSet r,int n)throws SQLException{return new CardView(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getObject(8,UUID.class),r.getString(9),r.getString(10),r.getObject(11)==null?null:r.getInt(11),r.getObject(12)==null?null:r.getInt(12),new CardView.Controls(r.getBoolean(13),r.getBoolean(14),r.getBoolean(15),r.getBoolean(16),r.getBoolean(17),r.getLong(18),r.getLong(19),r.getLong(20),r.getLong(21),r.getLong(22),r.getLong(23)),true);}
 private void validateKey(String k){if(k==null||!k.matches("[A-Za-z0-9_-]{16,100}"))throw new DomainException(HttpStatus.BAD_REQUEST,"INVALID_IDEMPOTENCY_KEY","A valid Idempotency-Key is required.");}
 private String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private DomainException notFound(){return new DomainException(HttpStatus.NOT_FOUND,"CARD_NOT_FOUND","Card was not found.");} private DomainException invalid(String c,String m){return new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,c,m);} private DomainException conflict(String c,String m){return new DomainException(HttpStatus.CONFLICT,c,m);}
 private record CardRow(long id,String status,String processor,long controlVersion){}
 private static final String VIEW="SELECT x.public_id,p.display_name,p.tier,p.funding_type,x.cardholder_name,x.masked_reference,x.status,a.public_id,a.nickname,a.masked_number,x.expiry_month,x.expiry_year,c.atm_enabled,c.online_enabled,c.pos_enabled,c.contactless_enabled,c.international_enabled,c.atm_limit_minor,c.online_limit_minor,c.pos_limit_minor,c.contactless_limit_minor,c.daily_limit_minor,c.version FROM cards x JOIN card_products p ON p.id=x.product_id LEFT JOIN bank_accounts a ON a.id=x.linked_account_id JOIN card_controls c ON c.card_id=x.id";
}
